PEOPLE = []
CHOICES = {}


def chapter(title, scene, memory, family, level, counter, count):
    body = {lang: scene[lang] + ' ' + ACTION[lang].format(FAMILY_NAMES[family][lang], level, COUNTER_ACTION[counter][lang].format(count)) for lang in LANGUAGES}
    return dict(title=title, body=body, memory=memory, family=family, level=level, counter=counter, count=count)


def person(id, name, residents, focus, thresholds, role, bio, greeting, chapters, repeat, choices):
    PEOPLE.append(dict(id=id, name=name, residents=residents, focus=focus, thresholds=thresholds, role=role, bio=bio, greeting=greeting, chapters=chapters, repeat=repeat))
    CHOICES[id] = choices


def step(title, scene, family, level, counter, count):
    # The title also names the permanently authored memory object in the resident log.
    return chapter(title, scene, title, family, level, counter, count)


